#!/usr/bin/env node

import fs from 'fs';
import path from 'path';
import process from 'process';
import { execSync } from 'child_process';
import { createRequire } from 'module';

import { Command } from 'commander';
import inquirer from 'inquirer';

import {
  Config,
  Documents,
  Eval,
  Finetune,
  Providers,
  Questionnaire,
  Rag,
  Scanners
} from 'frai-core';

const require = createRequire(import.meta.url);
const pkg = require('../package.json') as { version?: string; name?: string };

type LogLevel = 'info' | 'success' | 'warn' | 'error';
type LogMeta = Record<string, unknown> | undefined;

const DOC_FILENAMES = ['checklist.md', 'model_card.md', 'risk_file.md'];
const LOCAL_ENV_DISPLAY = '.env';
const GLOBAL_CONFIG_DISPLAY = '~/.config/frai/config';

type ScanResult = ReturnType<typeof Scanners.scanCodebase>;

interface GenerateOptions {
  scan?: boolean;
  ci?: boolean;
  key?: string;
  global?: boolean;
  exportPdf?: boolean;
  showConfig?: boolean;
}

interface ScanOptions {
  root?: string;
  ci?: boolean;
  json?: boolean;
  silent?: boolean;
}

interface EvalOptions {
  outputs: string;
  references?: string;
  report?: string;
  format?: 'json' | 'markdown';
}

interface RagOptions {
  input?: string | string[];
  output?: string;
  chunkSize?: number;
  extensions?: string[];
}

interface FinetuneTemplateOptions {
  output?: string;
}

interface FinetuneValidateOptions {
  readiness?: boolean;
}

const log = {
  info(message: string, meta?: LogMeta) {
    console.log(formatLog('info', message, meta));
  },
  success(message: string, meta?: LogMeta) {
    console.log(formatLog('success', message, meta));
  },
  warn(message: string, meta?: LogMeta) {
    console.warn(formatLog('warn', message, meta));
  },
  error(message: string, meta?: LogMeta) {
    console.error(formatLog('error', message, meta));
  }
};

function formatLog(level: LogLevel, message: string, meta: LogMeta = undefined) {
  const timestamp = new Date().toISOString();
  if (!meta || Object.keys(meta).length === 0) {
    return `[${timestamp}] ${level.toUpperCase()} ${message}`;
  }
  let serializedMeta = '';
  try {
    serializedMeta = JSON.stringify(meta);
  } catch (error) {
    serializedMeta = String(meta);
  }
  return `[${timestamp}] ${level.toUpperCase()} ${message} ${serializedMeta}`;
}

