export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds = {}
} = {}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const thresholdResults = Object.keys(thresholds).length > 0
    ? validateThresholds(thresholds, evaluations)
    : [];
  const passed = thresholdResults.length === 0 || thresholdResults.every(t => t.passed);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholdResults.length > 0) {
    report.passed = passed;
    report.thresholds = thresholdResults;
  }

  return report;
}

