import fs from 'fs';
import os from 'os';
import path from 'path';
import { afterEach, describe, expect, it } from 'vitest';

import {
  generateReport,
  loadDataset,
  parseThresholds,
  runEvaluations,
  validateThresholds,
  writeReport
} from './index.js';

const tmpDirs = [];
afterEach(() => {
  while (tmpDirs.length) {
    fs.rmSync(tmpDirs.pop(), { recursive: true, force: true });
  }
});

const createTempDir = () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-eval-'));
  tmpDirs.push(dir);
  return dir;
};

describe('Evaluation harness', () => {
  it('loads outputs and references', () => {
    const dir = createTempDir();
    const outputsPath = path.join(dir, 'outputs.json');
    const referencesPath = path.join(dir, 'references.json');
    fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World'], null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world'], null, 2));

    const dataset = loadDataset({ outputsPath, referencesPath });
    expect(dataset.outputs).toEqual(['Hello', 'World']);
    expect(dataset.references).toEqual(['hello', 'world']);
  });

  it('runs default evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const exact = evaluations.find((metric) => metric.id === 'exact_match');
    const toxicity = evaluations.find((metric) => metric.id === 'toxicity');

    expect(exact.score).toBeCloseTo(1, 4);
    expect(toxicity.score).toBe(1);
  });

  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('parses thresholds from strings', () => {
    const thresholds = parseThresholds(['exact_match=0.9', 'toxicity=0.8']);
    expect(thresholds).toEqual({
      exact_match: 0.9,
      toxicity: 0.8
    });
  });

  it('rejects malformed thresholds', () => {
    expect(() => parseThresholds(['exact_match'])).toThrow('Malformed threshold');
    expect(() => parseThresholds(['exact_match=abc'])).toThrow('is not a number');
    expect(() => parseThresholds(['exact_match=1.5'])).toThrow('must be between 0 and 1');
    expect(() => parseThresholds(['exact_match=-0.1'])).toThrow('must be between 0 and 1');
  });

  it('validates thresholds against evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'world'],
      references: ['hello', 'world']
    });
    const results = validateThresholds({ exact_match: 0.5, toxicity: 0.9 }, evaluations);
    expect(results).toHaveLength(2);
    expect(results[0].metric).toBe('exact_match');
    expect(results[0].min).toBe(0.5);
    expect(results[0].passed).toBe(true);
    expect(results[1].metric).toBe('toxicity');
    expect(results[1].passed).toBe(true);
  });

  it('rejects unknown metrics in thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    expect(() => validateThresholds({ unknown_metric: 0.5 }, evaluations)).toThrow('Unknown metric');
  });

  it('handles missing metric scores in thresholds', () => {
    const evaluations = [
      {
        id: 'exact_match',
        label: 'Exact Match',
        score: null,
        total: 0,
        details: 'No data'
      }
    ];
    const results = validateThresholds({ exact_match: 0.5 }, evaluations);
    expect(results[0].passed).toBe(false);
    expect(results[0].score).toBe(null);
  });

  it('generates report with thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'world'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.5, toxicity: 0.9 }
    });
    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(2);
    expect(report.thresholds[0].passed).toBe(true);
  });

  it('marks report as failed when thresholds not met', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'world'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z',
      thresholds: { exact_match: 0.99 }
    });
    expect(report.passed).toBe(false);
    expect(report.thresholds[0].passed).toBe(false);
  });

  it('does not include thresholds in report when none provided', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });
    expect(report.passed).toBeUndefined();
    expect(report.thresholds).toBeUndefined();
  });

  it('includes thresholds section in markdown report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'world'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5 }
    });
    const markdown = require('./reporters.js').toMarkdown(report);
    expect(markdown).toContain('## Thresholds');
    expect(markdown).toContain('exact_match');
    expect(markdown).toContain('PASS');
  });
});

